import {readinessIssues,readyToStartCutting,overdueDays} from './manufacturing.js';
export function workflowMatches(p,filter,worker){if(filter==='active')return ['Preparing','Cutting','Finishing'].includes(p.status);if(filter==='mine')return !!worker.trim()&&(p.owner?.toLowerCase()===worker.trim().toLowerCase()||p.assignedTo?.toLowerCase()===worker.trim().toLowerCase())&&p.status!=='Finished';if(filter==='ready')return readyToStartCutting(p);if(filter==='prep')return ['Not started','Preparing'].includes(p.status)&&!p.blocked&&readinessIssues(p).length>0;if(filter==='blocked')return p.blocked&&p.status!=='Finished';return true;}
export function nextJob(parts,worker=''){return parts.filter(p=>p.status!=='Finished'&&!p.blocked&&(!p.assignedTo||p.assignedTo.toLowerCase()===worker.trim().toLowerCase())&&(!p.owner||p.owner.toLowerCase()===worker.trim().toLowerCase())).sort((a,b)=>Number(b.owner===worker&&!!worker)-Number(a.owner===worker&&!!worker)||Number(readyToStartCutting(b))-Number(readyToStartCutting(a))||Number(overdueDays(b)>0)-Number(overdueDays(a)>0)||Number(b.priority==='High')-Number(a.priority==='High')||(a.due||'9999').localeCompare(b.due||'9999')||a.name.localeCompare(b.name))[0]||null;}
